using System.Globalization;

namespace UnicodeExplorer.Unicode;

/// <summary>Parses the data file generated by tools/UcdBuilder.cs (see docs/SPEC.md 5.3).</summary>
public static class DataFileParser
{
    public const int FormatVersion = 1;
    public const string UnicodeVersion = "18.0.0";
    /// <summary>Appended to the data URL so a data upgrade invalidates the browser cache.</summary>
    public const string CacheKey = $"{UnicodeVersion}-1";

    public static UnicodeDatabase Parse(string text)
    {
        var lines = text.Split('\n');
        var header = lines[0].Split(';');
        if (header.Length < 3 || header[0] != "#unicode-explorer-data" || header[1] != FormatVersion.ToString())
            throw new FormatException($"Unsupported data file format: '{lines[0]}'");

        var blocks = new List<BlockInfo>();
        var scripts = new List<ScriptRange>();
        var ranges = new List<CharRange>();
        var chars = new List<CharEntry>();
        var entities = new Dictionary<int, string[]>();
        var section = "";

        foreach (var line in lines.Skip(1))
        {
            if (line.Length == 0) continue;
            if (line[0] == '@') { section = line; continue; }

            var f = line.Split(';');
            switch (section)
            {
                case "@blocks":
                    blocks.Add(new BlockInfo(Hex(f[0]), Hex(f[1]), f[2], f[3]));
                    break;
                case "@scripts":
                    scripts.Add(new ScriptRange(Hex(f[0]), Hex(f[1]), f[2]));
                    break;
                case "@ranges":
                    ranges.Add(new CharRange(Hex(f[0]), Hex(f[1]), f[2], NullIfEmpty(f[3])));
                    break;
                case "@chars":
                    chars.Add(new CharEntry(Hex(f[0]), f[1], f[2],
                        OptionalHex(f[3]), OptionalHex(f[4]), OptionalHex(f[5]),
                        List(f[6]), NullIfEmpty(f[7])));
                    break;
                case "@entities":
                    entities[Hex(f[0])] = List(f[1]);
                    break;
            }
        }

        return new UnicodeDatabase
        {
            UnicodeVersion = header[2],
            Blocks = blocks,
            Scripts = scripts,
            Ranges = ranges,
            Chars = chars,
            Entities = entities,
        };
    }

    private static int Hex(string s) => int.Parse(s, NumberStyles.HexNumber, CultureInfo.InvariantCulture);

    private static int? OptionalHex(string s) => s.Length == 0 ? null : Hex(s);

    private static string? NullIfEmpty(string s) => s.Length == 0 ? null : s;

    private static string[] List(string s) => s.Length == 0 ? [] : s.Split('|');
}
